create table actor_state_history (bladder integer, comfort integer, emotion_arousal float(53), emotion_dominance float(53), emotion_intensity integer, emotion_pleasure float(53), energy integer, env_modifier integer, fun integer, health integer, hunger integer, hygiene integer, mood integer, social integer, thirst integer, urgency_level integer, created_at timestamp(6), game_second bigint, id bigint generated by default as identity, project_id bigint not null, dominant_emotion varchar(20), npc_type varchar(20), npc_ref varchar(50), urgency_text varchar(120), primary key (id), constraint uk_state_history_ref_second unique (project_id, npc_ref, game_second));
create table actor_story_plan (version integer not null, created_at timestamp(6), id bigint generated by default as identity, project_id bigint not null, task_id bigint, atmosphere_segment LONGTEXT, story_plan_json LONGTEXT, story_plan_md LONGTEXT, style_profile_json LONGTEXT, style_profile_md LONGTEXT, primary key (id));
create table actor_talk_group_member (created_at timestamp(6), id bigint generated by default as identity, session_id bigint not null, source varchar(16), character_ref varchar(32) not null, character_name varchar(64), primary key (id), constraint uk_talk_group_member_session_ref unique (session_id, character_ref));
create table actor_talk_message (seq integer, created_at timestamp(6), id bigint generated by default as identity, session_id bigint not null, role varchar(16), character_ref varchar(32), content LONGTEXT, meta_json LONGTEXT, primary key (id));
create table actor_talk_player_profile (created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), user_id bigint not null, name varchar(64), persona_json LONGTEXT, relation_settings_json LONGTEXT, primary key (id), constraint uk_talk_player_profile_user unique (user_id));
create table actor_talk_player_relation (affinity integer, trust integer, version integer, id bigint generated by default as identity, player_profile_id bigint, project_id bigint not null, updated_at timestamp(6), character_ref varchar(32), stage varchar(32), note varchar(500), state_summary varchar(500), primary key (id));
create table actor_talk_session (author_note_depth integer, author_note_frequency integer, player_relation_version integer, summary_message_count integer, created_at timestamp(6), frozen_game_second bigint, id bigint generated by default as identity, location_id bigint, project_id bigint not null, updated_at timestamp(6), user_id bigint, status varchar(16), type varchar(16), character_ref varchar(32), title varchar(100), location_name varchar(128), author_note varchar(1000), summary varchar(1000), frozen_snapshot_json LONGTEXT, primary key (id));
create table actor_talk_worldbook (enabled boolean, priority integer, created_at timestamp(6), id bigint generated by default as identity, project_id bigint not null, session_id bigint not null, updated_at timestamp(6), keyword varchar(100) not null, content LONGTEXT, primary key (id), constraint uk_talk_worldbook_session_keyword unique (session_id, keyword));
create table actor_test_run (command_count integer, intervene_count integer, created_at timestamp(6), end_game_second bigint, end_real_ms bigint, id bigint generated by default as identity, project_id bigint not null, start_game_second bigint, start_real_ms bigint, updated_at timestamp(6), status varchar(20), name varchar(100), eval_run_ids_json TEXT, purpose TEXT, summary_json LONGTEXT, primary key (id));
create table actor_test_run_event (seq integer, created_at timestamp(6), game_second bigint, id bigint generated by default as identity, real_ms bigint, run_id bigint not null, event_type varchar(20), action varchar(40), params_json TEXT, result_json LONGTEXT, state_snapshot_json LONGTEXT, primary key (id));
create table actor_test_usage_log (attempt integer, cache_hit_tokens integer, cache_miss_tokens integer, duration_ms integer, request_chars integer, response_chars integer, token_in integer, token_out integer, call_at timestamp(6), character_id bigint, created_at timestamp(6), game_second bigint, id bigint generated by default as identity, project_id bigint, provider_id bigint, status varchar(20), step_type varchar(30), run_label varchar(48) not null, scene varchar(48), trace_id varchar(64), model varchar(100), error_message varchar(500), base_url varchar(255), response_text LONGTEXT, system_prompt LONGTEXT, user_prompt LONGTEXT, primary key (id));
