create table actor_world_chronicle (importance integer, created_at timestamp(6), game_day bigint not null, game_hour bigint, id bigint generated by default as identity, project_id bigint not null, updated_at timestamp(6), season varchar(10), source varchar(20), decision_source varchar(32), title varchar(200) not null, content TEXT not null, event_ids TEXT, involved_characters TEXT, involved_entities TEXT, tags TEXT, weather_snapshot TEXT, primary key (id));
