create table actor_world_engine_tick_stat (ai_decisions integer, budget_total integer, budget_used integer, exhausted_decisions integer, fallback_decisions integer, missing_decisions integer, created_at timestamp(6), game_second bigint, id bigint generated by default as identity, project_id bigint not null, primary key (id));
